(43953, 'Songofsongs 2:5', 'Songofsongs', 2, 5, 'د کشمشو سره يې ما ته طاقت راکړلو، او د سيوانو سره يې زۀ تازه کړمه، ځکه د مينې په وجه مړاوې شوې ومه.', 'د کشمشو سره یې ما ته طاقت راکرلو، او د سیوانو سره یې زۀ تازه کرمه، جکه د مینې په وجه مراوې شوې ومه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43954, 'Songofsongs 2:6', 'Songofsongs', 2, 6, 'د هغۀ ګس لاس زما د سر لاندې وونه، او د هغۀ ښى لاس ځانته راغاړه ايستمه.', 'د هغۀ ګس لاس زما د سر لاندې وونه، او د هغۀ شی لاس جانته راغاره ایستمه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43955, 'Songofsongs 2:7', 'Songofsongs', 2, 7, 'اے د يروشلم جينکو، ما سره ټينګه وعده وکړئ، ترڅو چې مونږ پراتۀ يونه مونږ به نۀ په عذابوئينه.', 'اے د یروشلم جینکو، ما سره تینګه وعده وکری، ترچو چې مونز پراتۀ یونه مونز به نۀ په عذابویینه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43956, 'Songofsongs 2:8', 'Songofsongs', 2, 8, 'وګوره، چې جانان مې راروان دېنه، هغه په غرونو راخېژينه، او په غونډو ټوپونه وهينه.', 'وګوره، چې جانان مې راروان دېنه، هغه په غرونو راخېژینه، او په غوندو توپونه وهینه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43957, 'Songofsongs 2:9', 'Songofsongs', 2, 9, 'زما جانان لکه هوسۍ او يا د ځوان هوسۍ په شان دېنه، وګوره هغه اوس زمونږ د دېوال شاته ولاړ دېنه، هلته د کړکۍ د جال نه دننه کوټې ته ګورينه.', 'زما جانان لکه هوسی او یا د جوان هوسی په شان دېنه، وګوره هغه اوس زمونز د دېوال شاته ولار دېنه، هلته د کرکی د جال نه دننه کوتې ته ګورینه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43958, 'Songofsongs 2:10', 'Songofsongs', 2, 10, 'زما جانان ما ته ووئيل، محبوب ”زما محبوبې، راپاڅه، ښائسته محبوبې، راځه ما سره لاړه شه.', 'زما جانان ما ته ووییل، محبوب ”زما محبوبې، راپاچه، شایسته محبوبې، راجه ما سره لاره شه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43959, 'Songofsongs 2:11', 'Songofsongs', 2, 11, 'وګوره، ژمې تېر شو بارانونه ودرېدل او بس شونه.', 'وګوره، ژمې تېر شو بارانونه ودرېدل او بس شونه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43960, 'Songofsongs 2:12', 'Songofsongs', 2, 12, 'په زمکه ګلونه راښکاره شونه، د سندرو وئيلو موسم رارسېدلے دېنه، زمونږ په مُلک کښې د ګوګوشتکو آوازونه اورېدلے کيږينه.', 'په زمکه ګلونه راشکاره شونه، د سندرو وییلو موسم رارسېدلے دېنه، زمونز په ملک کشې د ګوګوشتکو اوازونه اورېدلے کیزینه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842);